      "id": "FAM:SF-APPS-049",
      "status_as_recorded": "rejected",
      "finding": "52-series sequential adaptation: durable pivot branches and net swing: If-X-fails-then-Y pivot branches and PT net-swing are durable across ~104 playoff team-offense units. Result: durable_branches=[]. Median net swing: CUT +0.36 (neg in 9%), TRANSITION +0.26 (21%), PULL_UP +0.09 (33%), PNR +0.04 (45%), SPOT_UP +0.02 (40%), POST_UP -0.22 (77%), DRIVE -0.27 (88%)."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-CHT-039",
      "what_failed": "Series-level AVOID share vs winning, confounded by team quality and underpowered (n=50; need ~80).",
      "why": "confounding and small sample size; rho=-0.26 p=0.07 did not reach significance."
    },
    {
      "id": "FAM:SF-APPM-016",
      "what_failed": "Possession-level test of engine-recommended play type scoring advantage beyond inherent PT PPP.",
      "why": "Strictest fixed-effects test gave null result (p=0.71); earlier A/B tests explained by engine picking high-PPP play types."
    },
